from __future__ import annotations

from sh3dev.commands.base import BaseCommand
from sh3dev.generators import (
    GitHubIssueGenerator,
)
from sh3dev.integrations import (
    GitHubIssue,
)
from sh3dev.protocols import CommandMetadata


class GitHubCommand(BaseCommand):
    """
    GitHub integration commands.
    """

    metadata = CommandMetadata(
        name="github",
        description="GitHub integration",
        category="integration",
    )

    def __init__(
        self,
    ) -> None:

        self._generator = GitHubIssueGenerator()

    def execute(
        self,
        args: list[str],
    ) -> object:

        if not args:
            return "Usage: github issue"

        if args[0] != "issue":
            return f"Unknown action: {args[0]}"

        issue = GitHubIssue(
            title=("[SH-3 RFC] Development Task"),
            body=("Generated by SH-3 DevKit.\n\n## Specification\n\nImplement SH-3 component."),
            labels=(
                "SH-3",
                "development",
            ),
        )

        result = self._generator.generate(
            issue,
            ".github/issues/task.md",
        )

        return f"Generated: {result}"
